using System;
using ModernUO.Serialization;

namespace Server.Items;

/// <summary>
/// A rare or legendary fish (FishInfo lists them): one per catch, not stackable, weighed, and it remembers who caught it
/// and when. The Fishing patch (Fishing-high-seas-fish.patch, Give) stamps all of that when the fish lands in the pack,
/// as ServUO's Fishing.Give does. GetProperties shows the fisher and the date, as ServUO's does.
/// </summary>
[SerializationGenerator(0, false)]
public partial class RareFish : BaseHighseasFish
{
    [SerializedCommandProperty(AccessLevel.GameMaster)]
    [SerializableField(0)]
    private Mobile _fisher;

    [SerializedCommandProperty(AccessLevel.GameMaster)]
    [SerializableField(1)]
    private DateTime _dateCaught;

    public RareFish(int itemID) : base(itemID)
    {
    }

    public override void GetProperties(IPropertyList list)
    {
        base.GetProperties(list);

        list.Add(1070857, _fisher != null ? _fisher.Name : "An Unknown Fisher"); // Caught by ~1_fisherman~

        if (_dateCaught != DateTime.MinValue)
        {
            list.Add($"[{_dateCaught.ToShortDateString()}]");
        }
    }
}

